INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b6168e1e-19a5-47e7-80ec-6f4395333e9c', '21feff02-016d-46e2-bb9d-c27495133b1b', '1. óra: Az év bevezetése, ismétlés, játékos bevezető', 'Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "55154061-ad2d-430b-804c-a02e219aaf03", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "8b8231e3-5d3d-4d32-8d39-a7a71222f89b", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "afea8159-01fa-433d-82d8-2e063a934f14", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "2be3ef39-1d99-41d2-8454-5fbb17971346", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "bc07393b-dc66-497a-beed-3254fb00131c", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "2f47c1e2-a3e9-46d9-8a07-a7881137accc", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "f7f525c2-14d8-47ad-81d5-204c795f7ba1", "text": "Igaz", "isCorrect": true}, {"id": "f6d0c92e-583a-4597-9e16-7df6e674b6d2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c0b9fa40-ef9c-4448-b713-434d7bbcd35b", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "8b78d500-66f5-4d75-8315-0c9df8dd5af5", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "70d0c0d5-dac2-4df5-8a5f-013f8d6f0eed", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "f6d44d9b-cac3-4e12-ab12-4f1db295461d", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "a8dd240a-c49a-4182-94eb-74151bb52c7d", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "34016c0e-42e8-4dac-94ff-c4e52b3cbf95", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "97e7c84d-4d22-4d2f-a865-bf579e5c1e71", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "27e23cd7-3056-4af2-8750-a1a0170a7e5e", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "885762fc-34a4-4e15-bfa1-9aff27ab406b", "text": "Igaz", "isCorrect": true}, {"id": "b69aef73-4b6a-4420-a52c-7e73d9b27b51", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "075cf802-27ea-4844-b643-96c4bf7643a4", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e72d1ac7-f644-47a8-98c2-d809a980d2e6', '21feff02-016d-46e2-bb9d-c27495133b1b', '2. óra: Játékok', 'Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "88532d16-c7af-4fce-95ca-becb7035d0ce", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "9bed5c96-b868-454b-b1cd-6b4a077710bb", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "7ee89107-14c9-483e-a482-fe76759d8a70", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "8b5780a0-0d21-42d9-8d56-b7ff26224fde", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "79e2b082-6b37-4b7b-8c6b-9a27919db1ca", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "df39d51e-725b-47df-ab38-850b61f7393b", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "ef68d9a0-3eeb-4a98-8894-d0ecf6254b21", "text": "Igaz", "isCorrect": true}, {"id": "2520ddeb-f4e6-4873-9477-3d41179269db", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "63b351ae-b31c-4dc8-8cfb-7d1c3a8b75ee", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "995b7186-f858-4915-ab10-2293963e67d8", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "004e085a-1921-41de-8fc6-d4af9b23eb36", "text": "Sudoku", "isCorrect": true}, {"id": "ffc182e6-1be3-4948-99a3-3e3bc2aa83e3", "text": "Fócsoport", "isCorrect": false}, {"id": "86758440-1f78-4eb8-9621-64b64d9df413", "text": "Futóverseny", "isCorrect": false}, {"id": "82237637-0abb-4a9b-89e1-75157f9586c8", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "583c756c-56cc-4423-8ed8-89adbaecdfc6", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "5375eaad-3ed6-4502-9a59-2dfef318fac1", "text": "Igaz", "isCorrect": true}, {"id": "ac8fbf67-f7b1-4693-b6c9-fc145613ef47", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e92e5e04-bbae-4e30-bd43-623a1b827197", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "9ba1d7d2-d480-4bba-b762-0693677d053d", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "1c973303-27a4-4e4d-b463-992006138557", "text": "Igaz", "isCorrect": true}, {"id": "4a9aa188-f3fd-4568-a7d5-7640d0dfaf96", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9fd40fc9-46e0-4b96-9126-4868ebdcd83e', '21feff02-016d-46e2-bb9d-c27495133b1b', '3. óra: Év eleji diagnosztikus felmérés', 'Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "89b89871-43c8-4114-b3b2-218b24e7f288", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "254709f7-8833-495b-9152-0e40f6bcc172", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "84a41be0-338d-4c73-9df1-d42650ee712f", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "1d12f63f-2746-46fd-8b21-097ef3642cbb", "text": "2/4", "isCorrect": false}, {"id": "32baff01-6d9b-4c6f-808a-8dff69a272ed", "text": "4/8", "isCorrect": false}, {"id": "36725b93-aa9e-45f2-a051-ba9a1f5e3b8e", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "d23fb5bd-66a0-44f6-804e-a7be1ef49b3c", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "03928721-7aad-4b5a-98ee-799c210e7a14", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "49f93ab8-e052-4f16-a4a0-636e35b42522", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "4da06b1f-784c-482e-a713-26d08bf1d946", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "438d6f82-28e8-4e35-b29a-5597b3ce50c2", "text": "Igaz", "isCorrect": true}, {"id": "63549f95-5210-457d-8cd9-ad241d369c0d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "72ff037b-0c34-498b-87e1-3001fa945429", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "cac0811e-57b4-498c-ba1c-67f44cf270bd", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "31b085ad-c576-4ed7-8cbf-29dddcf4bc7f", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "06297627-4c48-4fbb-a888-a4af8e8ca917", "text": "Igaz", "isCorrect": true}, {"id": "2bf72e3a-2228-4217-bc81-d2a2a52b037a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5ccfcdec-706b-4da4-aca9-9d6c14f94ddd", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('e6c8619a-5f2f-4f66-8540-3e9cc104c79e', '21feff02-016d-46e2-bb9d-c27495133b1b', '4. óra: Műveletek az egész számok körében', 'Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "c0c3c865-1846-45e1-9578-aea46caff239", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "3ef01f55-800d-4776-a8a0-d4bdf289ef6b", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "e9fdcf9d-022f-4bd1-9515-42bdc64addbb", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "121e8e64-a22d-4dc4-b4d6-b70947713e65", "text": "Igaz", "isCorrect": true}, {"id": "31a6ecbd-3ece-4bc0-8ff5-7712f5596ef1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "da13604a-7e60-4176-931b-7354649d88d6", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "90cfa800-2495-4189-be60-d028f9c57883", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "ace8566e-691e-4da6-ab57-95bb417be397", "text": "-8", "isCorrect": true}, {"id": "d2ec00c6-3fe7-472c-9596-f39542d2a839", "text": "-15", "isCorrect": false}, {"id": "7e1a69e1-692b-40e4-a258-df0ca8f6818f", "text": "Egyenlőek", "isCorrect": false}, {"id": "efc76879-2cbe-4710-8378-f57b6d9c1a14", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "fbcc122b-bc88-4fe4-93d1-8a5ec1b13fab", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "8974b658-66a3-43c5-ab34-9fd7fb2cc5e4", "text": "Igaz", "isCorrect": true}, {"id": "6414d1a9-c86b-49da-be3c-9a4f163f51ec", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b4f973d5-922b-4855-a49b-2bf3ade9348a", "text": "Mennyi (-10) + (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('bc78cdb3-609e-4c1e-9cec-0b6ca7d6dfc6', '21feff02-016d-46e2-bb9d-c27495133b1b', '5. óra: Az egész számok szorzása', 'Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "0c147b55-b068-4959-97c3-121eeabdcc16", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "7df88d87-d879-4c7e-8aca-460107b236eb", "text": "Pozitív (+)", "isCorrect": true}, {"id": "90157a25-80f2-4c2c-94d2-a73a832059c8", "text": "Negatív (-)", "isCorrect": false}, {"id": "63a7df9b-fd3e-4df7-8017-94e68fa19963", "text": "Mindig 0", "isCorrect": false}, {"id": "e19ac807-39e3-4fcd-8cb4-aec35d96590f", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "b5747b45-2f57-48e8-a764-91af62d4df04", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "28500643-636d-46f9-8d49-cdcc8de4cd8d", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "80b2d31c-cb27-4e91-a65f-4b62fa8966fe", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "ddfbe8e5-df76-4c86-9ca3-890bfaecda7d", "text": "Igaz", "isCorrect": true}, {"id": "444589df-eb23-490a-9aaf-7f0aeecfc98d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7c01d1de-3c20-4c63-8254-6a08548d109d", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "db13ea6c-f610-466c-9521-a24307c20193", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "eba4310d-43cf-4ba7-8bb7-cce65d15b5fa", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "1b3522df-b3b1-499e-9c9d-4f06905c0926", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "232f4d05-8d3c-433e-b612-a004fc600b1c", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('36d17a2f-18d6-4e63-a6dc-2805bfb259c0', '21feff02-016d-46e2-bb9d-c27495133b1b', '6. óra: Gyakorlóóra: az egész számok szorzása', 'Több tényező előjelének meghatározása, szorzások gyakorlása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "f20e1167-a64a-4182-a874-b6e534e98bfd", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "bd798e48-51a0-4981-94cc-53f15c775859", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "7a3a17a5-e0b8-4c28-9af8-4aef24e5d4dd", "text": "Pozitív", "isCorrect": true}, {"id": "923e8094-acc1-44ba-9dc2-3288bf4ae7ae", "text": "Negatív", "isCorrect": false}, {"id": "711c71d6-c3ec-4b6b-bceb-04a8167e583a", "text": "Nulla", "isCorrect": false}, {"id": "d94b06d6-5a76-4c43-ade2-854f128ed05a", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "bff5d77b-9af8-4a53-8b51-3c6f6f9cf623", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "0c264a72-e8bb-4e1f-b603-28402fead5fd", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "3568256e-abb0-4788-a044-2002f8ec4da8", "text": "Igaz", "isCorrect": true}, {"id": "f8c05f20-410b-465a-9022-4103d5353f25", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6364a0c2-805b-479d-9144-7dc3e2825491", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "498e4b9a-ee55-4085-b63b-a4f13e16c311", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "972bf565-28da-4fc1-acdb-41ddf7aad49a", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "b79ae65c-4072-4655-a91f-dcd2ac62ee90", "text": "Igaz", "isCorrect": true}, {"id": "ad45159a-59b9-4610-88ed-88b02cf11faf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('9b4ce7dd-8d6b-4d30-9785-29273fe4301b', '21feff02-016d-46e2-bb9d-c27495133b1b', '7. óra: Az egész számok osztása', 'Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "fb4d8b36-e21a-4462-bafa-23a1c5d23c4c", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "39550dca-3633-46fd-8fe6-416b3bde750c", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "ed806209-b627-4548-b223-e118a600367f", "text": "Mindig negatív", "isCorrect": false}, {"id": "995404f0-d986-4717-aa53-b420dca8ecd7", "text": "Mindig pozitív", "isCorrect": false}, {"id": "b3c18809-0aa8-4dc9-94d4-46e7b4d899ec", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "c33fe5fe-c99a-4c0b-b77b-2cb9e971b441", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "5a2ee38e-40f1-4d99-a531-657c7d29819c", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "decab23b-504c-4896-8341-48ff43c50ee6", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "2eac4b22-c1bb-44aa-a33e-942813fbbf9f", "text": "Igaz", "isCorrect": true}, {"id": "c2b49aee-6742-421c-a5ef-344e6602776a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f737a5b9-1c56-4836-afe4-b0d5875f79e1", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "aa7204a2-9577-4bac-bb0e-11e1e7575c75", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "8bc90e5f-89a0-4661-b804-fff7ddd7974b", "text": "Igaz", "isCorrect": true}, {"id": "933a7abe-f1e2-4f5f-bc87-75d61953f39f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a5c4ae6c-6673-4c98-9a21-f23e2d0376d7", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c9f06213-41be-4a71-9927-c82837ae8b0b', '21feff02-016d-46e2-bb9d-c27495133b1b', '8. óra: Az egész számok osztásának gyakorlása', 'Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "7531ad58-dd13-4136-90ad-6065909e8aed", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "9b4e057b-96a5-4144-ac27-4c2c92c01287", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "4859d506-80c5-4cc5-bdc0-abd2e487ff1e", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "8911a7c1-30bb-488c-b5ee-0c27f2ac00f5", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "ca7110a6-6663-498c-a87c-3abda1ab052b", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "f4b0debf-a642-47a3-98bc-5a4db4c5c396", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "56cf20d7-161e-41cc-958f-972269351573", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "87e167f9-0b3a-4a47-bb1a-0dd7bb922ef8", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "17148263-caf2-43a0-b723-0a0040ea00eb", "text": "Igaz", "isCorrect": true}, {"id": "eb32eab0-a843-4262-ab38-460c43b3070a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "37f2f3bf-7eac-42a6-bbac-3d0f72dda44a", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "d0f7f3ed-5f20-4745-a239-cb0cab1ad8c0", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "82477db4-dded-44ae-87dd-ca3d245d2951", "text": "Igaz", "isCorrect": true}, {"id": "7b6bb4d2-bae7-4cd2-9d7c-db89a21a9033", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8d375120-258a-48d4-ad47-966307419224", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('033569a8-f274-466a-9e54-a4f2a5e00f2b', '21feff02-016d-46e2-bb9d-c27495133b1b', '9. óra: Hány eset van? Számoljuk össze!', 'Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "c9b1370b-1260-4b1e-bd9e-6f9cde15c592", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "c7a4d436-8a1b-4995-b4d5-6e808306d030", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "1acb3cfb-e2b8-4c5d-83c7-7359a9539eb1", "text": "Szögmérőt", "isCorrect": false}, {"id": "99578480-d880-4aa8-8ec5-7b6c87ca58d1", "text": "Körzőt", "isCorrect": false}, {"id": "cdffcd42-b71c-4bc4-9ce0-4cd37df4f008", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "810e7c51-5f63-43c0-b445-b08346d66820", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "1aa6b97f-2c35-493e-838e-2f4e96f3f1ad", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "7aeecaa7-0880-4351-bffc-1ac250d8136a", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "7fb78240-d2f6-444f-abb7-cae6ac1b9fe8", "text": "Igaz", "isCorrect": true}, {"id": "63d1d306-5067-4811-80a7-7e725cd88a8c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3355571a-9c05-49a3-b5fe-41e2211c0908", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "57e15d2b-b4e6-429a-9e53-1aa5c2253b82", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "20d56f42-380c-41e6-84dd-fe462603b073", "text": "Igaz", "isCorrect": false}, {"id": "6b501a03-5ba0-42fd-a69a-9194139ef1e5", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "7ae5b5fd-41ac-42fa-ad76-a55e79b11cc9", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('2456a78c-64ea-4d2a-86a5-79cb57416477', '21feff02-016d-46e2-bb9d-c27495133b1b', '10. óra: Gyakorlóóra. Hány eset van? Számoljuk össze!', 'Összeszámlálási feladatok gyakorlása fagráffal és táblázattal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "6a21e487-414f-42bf-84a5-53af03811558", "text": "Hány 2 jegyű páros szám képezhető az 1, 2, 3 számjegyekből (számjegyismétlés nélkül)?", "type": "multiple-choice", "options": [{"id": "8d42ad83-fda5-4423-97c3-dc4a83f1cb4f", "text": "2 (12, 32)", "isCorrect": true}, {"id": "1562f7bb-d832-40e6-b0aa-94ecb095d374", "text": "3", "isCorrect": false}, {"id": "bb6fe9e2-0108-4651-947f-3f44704784c8", "text": "4", "isCorrect": false}, {"id": "97025953-39a0-4103-a839-260fd5bee8d6", "text": "6", "isCorrect": false}], "timeLimit": 15}, {"id": "8e8eb5e5-92ea-414e-a601-434ea7309665", "text": "Három barát köszöntésekor (mindenki mindenkivel kezet fog) hány kézfogás történik?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "3602ca93-754d-4459-a175-d9f7877590ad", "text": "A fagráf ágai az egyes döntési lépéseket ábrázolják.", "type": "true-false", "options": [{"id": "a65897e2-24af-43ca-9ed2-916a50c7cd1f", "text": "Igaz", "isCorrect": true}, {"id": "1a6d7494-5d13-4f95-8bff-c9a5f957fd90", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2e1f3d41-38a4-4a25-a3f1-ad42fe1de184", "text": "Hány különböző sorrendben futhat be a célba 3 versenyző (A, B, C)? (3! = 3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "2832d3f7-5935-4246-be42-1275008c9c08", "text": "Ha 4 csapat játszik körmérkőzést (mindenki mindenkivel egyszer), hány mérkőzést játszanak összesen?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "fa106ef7-8693-4be8-9127-a65a050ec034", "text": "Egy szabályos dobókocka eldobásakor 6-féle kimenetel lehetséges.", "type": "true-false", "options": [{"id": "9ac641c7-2d12-475e-bd68-8471997a8a37", "text": "Igaz", "isCorrect": true}, {"id": "0693ded2-55ce-4827-9a64-755362009dbc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "02c6c829-d6c6-407b-b7ea-bd454d76f45f", "text": "Hány kétjegyű szám képezhető a 0 és 5 számjegyekből (0 nem lehet az első számjegy)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;